package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;
@Document("pricing_rules") public class PricingRules{@Id private String id="default";private double holidayMultiplier=1.2;private double demandMultiplier=1.1;private double availabilityMultiplier=1.15;private double leadTimeMultiplier=1.1;private long demandBookingsThreshold=10;private int lowInventoryThreshold=3;private int holidayMonth=12;public String getId(){return id;}public void setId(String x){id=x;}public double getHolidayMultiplier(){return holidayMultiplier;}public void setHolidayMultiplier(double x){holidayMultiplier=x;}public double getDemandMultiplier(){return demandMultiplier;}public void setDemandMultiplier(double x){demandMultiplier=x;}public double getAvailabilityMultiplier(){return availabilityMultiplier;}public void setAvailabilityMultiplier(double x){availabilityMultiplier=x;}public double getLeadTimeMultiplier(){return leadTimeMultiplier;}public void setLeadTimeMultiplier(double x){leadTimeMultiplier=x;}public long getDemandBookingsThreshold(){return demandBookingsThreshold;}public void setDemandBookingsThreshold(long x){demandBookingsThreshold=x;}public int getLowInventoryThreshold(){return lowInventoryThreshold;}public void setLowInventoryThreshold(int x){lowInventoryThreshold=x;}public int getHolidayMonth(){return holidayMonth;}public void setHolidayMonth(int x){holidayMonth=x;}}
